<?php
require "auth.php"; require "../config/database.php"; $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); $stmt=$conn->prepare("SELECT * FROM berita WHERE id=?");$stmt->bind_param("i",$id);$stmt->execute();$row=$stmt->get_result()->fetch_assoc();if(!$row)die("Berita tidak ditemukan.");$error="";
if($_SERVER['REQUEST_METHOD']==='POST'){
 $judul=trim($_POST['judul']);$isi=trim($_POST['isi']);$penulis=trim($_POST['penulis']);$status=$_POST['status']==='draft'?'draft':'published';$gambar=$row['gambar'];
 if(!empty($_FILES['gambar']['name'])){$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$type=mime_content_type($_FILES['gambar']['tmp_name']);if(!isset($allowed[$type]))$error="Format gambar tidak didukung.";else{$name=bin2hex(random_bytes(8)).'.'.$allowed[$type];if(move_uploaded_file($_FILES['gambar']['tmp_name'],"../assets/images/berita/".$name))$gambar="assets/images/berita/".$name;}}
 if(!$error){$stmt=$conn->prepare("UPDATE berita SET judul=?,gambar=?,isi=?,penulis=?,status=? WHERE id=?");$stmt->bind_param("sssssi",$judul,$gambar,$isi,$penulis,$status,$id);$stmt->execute();header("Location: berita.php");exit;}
}
?><!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Berita</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container section"><a href="berita.php">← Kembali</a><h1>Edit Berita</h1><?php if($error): ?><div class="alert"><?= htmlspecialchars($error) ?></div><?php endif; ?><form class="form" method="post" enctype="multipart/form-data"><label>Judul<input name="judul" value="<?= htmlspecialchars($row['judul']) ?>" required></label><label>Penulis<input name="penulis" value="<?= htmlspecialchars($row['penulis']) ?>" required></label><label>Gambar<input type="file" name="gambar" accept="image/*"></label><label>Isi Berita<textarea name="isi" rows="12" required><?= htmlspecialchars($row['isi']) ?></textarea></label><label>Status<select name="status"><option value="published" <?= $row['status']=='published'?'selected':'' ?>>Published</option><option value="draft" <?= $row['status']=='draft'?'selected':'' ?>>Draft</option></select></label><button>Simpan Perubahan</button></form></main></body></html>